def link_receipts(apps, schema_editor):
    """An order's one receipt becomes one of its receipts, its lines matched by material; lines take the order's status."""
    MaterialOrder = apps.get_model("production", "MaterialOrder")
    MaterialReceiptLine = apps.get_model("production", "MaterialReceiptLine")
    for order in MaterialOrder.objects.all():
        status = order.status if order.status in ("ordered", "in_transit", "customs") else "in_transit"
        order.lines.update(status=status)
        if order.receipt_id:
            order.receipt.order = order
            order.receipt.save(update_fields=["order"])
            for line in order.lines.all():
                MaterialReceiptLine.objects.filter(receipt_id=order.receipt_id, material_id=line.material_id).update(
                    order_line=line
                )


